function localPoint(event){const r=overlay.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top};}
function snapped(p){return state.snap?{x:snap(p.x),y:snap(p.y)}:p;}
function findPort(p,exclude=new Set()){
  let result=null,best=13/camera.zoom;const ids=scene.index.query({x:p.x-best-10,y:p.y-best-10,maxX:p.x+best+10,maxY:p.y+best+10});
  for(const id of ids){const n=store.nodes.get(id);if(!n||exclude.has(id))continue;for(const name of TYPES[n.type].ports){const q=portPosition(n,name),d=distance(p,q);if(d<best){best=d;result=q;}}}return result;
}
function endpointAt(p){const port=findPort(p);return port?{node:port.node,port:port.port}:snapped(p);}
