  if(o.kind==='node'){
    const rp=transform(o,0,-o.h/2-27/camera.zoom);if(distance(p,rp)<tolerance)return{type:'rotate',id:o.id};
    for(const [sx,sy]of[[-1,-1],[1,-1],[1,1],[-1,1]])if(distance(p,transform(o,sx*o.w/2,sy*o.h/2))<tolerance)return{type:'resize',id:o.id,sx,sy};
  }else{const pts=routeEdge(o,store.nodes);for(let i=0;i<pts.length;i++)if(distance(p,pts[i])<tolerance)return{type:i===0||i===pts.length-1?'endpoint':'waypoint',id:o.id,index:i,end:i===0?'from':'to',points:pts};}
