  c.fillStyle='#47716e';c.font='600 20px Inter, Segoe UI, Arial';c.fillText('NEXORA',53,y+30);c.font='9px Inter, Segoe UI, Arial';c.fillStyle='#92a3ab';c.fillText('CONNECTED PLANT ENGINEERING',54,y+48);c.font='13px Inter, Segoe UI, Arial';c.fillStyle='#607d87';c.fillText(d.name,235,y+29);c.font='10px Inter, Segoe UI, Arial';c.fillStyle='#9aaaae';c.fillText(store.meta.name.slice(0,55)+' · Not for construction',235,y+47);
  c.font='9px Inter, Segoe UI, Arial';c.fillText('DRAWING NUMBER',d.width-483,y+18);c.fillText('REVISION',d.width-219,y+18);c.fillStyle='#587381';c.font='600 15px Inter, Segoe UI, Arial';c.fillText(`${store.meta.number}-${d.code}`,d.width-483,y+42);c.fillText(d.revision,d.width-219,y+42);c.font='9px Inter, Segoe UI, Arial';c.fillStyle='#9caaaf';c.fillText('SHEET 1 OF 1',d.width-128,y+43);
