function drawOverlay(data){
  const c=worldContext(overlay),z=camera.zoom;c.textBaseline='middle';
  if(state.labels)for(const t of data.texts){if(t.size*z<4)continue;c.font=`${t.weight} ${t.size}px Inter, Segoe UI, Arial`;c.textAlign=t.align==='left'?'left':'center';if(t.background){const w=c.measureText(t.text).width;c.fillStyle='#ffffffed';c.fillRect(t.x-w/2-3,t.y-t.size/2-2,w+6,t.size+4);}c.fillStyle=t.color;c.fillText(t.text,t.x,t.y);}
  c.textAlign='center';
  for(const id of state.selected){const o=objectFor(id);if(!o||o.docId!==state.docId||state.layers[o.layer]===false)continue;c.strokeStyle='#008d83';c.fillStyle='#0896890b';c.lineWidth=1.1/z;
    if(o.kind==='node'){const b=nodeBounds(o);c.save();c.translate(o.x,o.y);c.rotate((o.rotation||0)*Math.PI/180);c.setLineDash([4/z,3/z]);c.fillRect(-o.w/2-5/z,-o.h/2-5/z,o.w+10/z,o.h+10/z);c.strokeRect(-o.w/2-5/z,-o.h/2-5/z,o.w+10/z,o.h+10/z);c.setLineDash([]);if(state.selected.size===1){for(const [x,y]of[[-o.w/2,-o.h/2],[o.w/2,-o.h/2],[o.w/2,o.h/2],[-o.w/2,o.h/2]]){c.fillStyle='white';c.fillRect(x-3/z,y-3/z,6/z,6/z);c.strokeRect(x-3/z,y-3/z,6/z,6/z);}c.beginPath();c.moveTo(0,-o.h/2-6/z);c.lineTo(0,-o.h/2-23/z);c.stroke();c.beginPath();c.arc(0,-o.h/2-27/z,3.5/z,0,Math.PI*2);c.fillStyle='white';c.fill();c.stroke();}c.restore();}
    else {const points=routeEdge(o,store.nodes);c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.lineWidth=4/z;c.strokeStyle='#008d8344';c.stroke();c.lineWidth=1/z;c.strokeStyle='#008d83';for(const p of points){c.fillStyle='white';c.fillRect(p.x-3/z,p.y-3/z,6/z,6/z);c.strokeRect(p.x-3/z,p.y-3/z,6/z,6/z);}}
  }
  const portNodes=new Set([...state.selected]);if(state.hover)portNodes.add(state.hover);if(state.port)portNodes.add(state.port.node);
  for(const id of portNodes){const n=store.nodes.get(id);if(!n||n.docId!==state.docId||state.layers[n.layer]===false)continue;for(const name of TYPES[n.type].ports){const p=portPosition(n,name);c.beginPath();c.arc(p.x,p.y,2.7/z,0,Math.PI*2);c.fillStyle='#fff';c.strokeStyle='#499f97';c.lineWidth=1/z;c.fill();c.stroke();}}
  if(state.port){c.beginPath();c.arc(state.port.x,state.port.y,7/z,0,Math.PI*2);c.fillStyle='#00a08c22';c.strokeStyle='#00a08c';c.lineWidth=1.4/z;c.fill();c.stroke();}
  if(state.marquee){const a=state.marquee.start,b=state.marquee.end;c.fillStyle='#0e99850d';c.strokeStyle='#008e85';c.lineWidth=1/z;c.setLineDash([4/z,3/z]);c.fillRect(a.x,a.y,b.x-a.x,b.y-a.y);c.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y);c.setLineDash([]);}
  if(state.connection&&state.pointer){const conn=state.connection,to=state.port?{node:state.port.node,port:state.port.port}:snapped(state.pointer);const edge={from:conn.from,to,waypoints:conn.waypoints,orthogonal:state.ortho};const points=routeEdge(edge,store.nodes);c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.strokeStyle=conn.type==='signal'?PALETTE.signal:PALETTE.pipe;c.lineWidth=2/z;c.setLineDash([6/z,4/z]);c.stroke();c.setLineDash([]);for(const p of points){c.fillStyle='#fff';c.strokeStyle='#299d8c';c.beginPath();c.arc(p.x,p.y,3/z,0,Math.PI*2);c.fill();c.stroke();}}
  if(state.tool==='insert'&&state.insertType&&state.pointer){const p=snapped(state.pointer),def=TYPES[state.insertType],g=symbolGeometry({x:p.x,y:p.y,w:def.w,h:def.h,type:state.insertType,tag:'',description:'',rotation:0});c.globalAlpha=.55;c.strokeStyle=PALETTE.accent;c.lineWidth=1.5/z;for(const l of g.lines){c.beginPath();c.moveTo(l.a.x,l.a.y);c.lineTo(l.b.x,l.b.y);c.stroke();}c.globalAlpha=1;}
}
const minimapCache={canvas:document.createElement('canvas'),key:''};
function drawMinimap(){
  const canvas=el('minimap'),c=canvas.getContext('2d'),d=doc();c.clearRect(0,0,canvas.width,canvas.height);if(!state.minimap)return;
  const scale=Math.min((canvas.width-14)/d.width,(canvas.height-12)/d.height),ox=(canvas.width-d.width*scale)/2,oy=(canvas.height-d.height*scale)/2,key=state.docId+'|'+scene.revision;
  if(minimapCache.key!==key){minimapCache.key=key;minimapCache.canvas.width=canvas.width;minimapCache.canvas.height=canvas.height;const b=minimapCache.canvas.getContext('2d');b.translate(ox,oy);b.scale(scale,scale);b.fillStyle='white';b.fillRect(0,0,d.width,d.height);
    for(const entry of scene.entries.values()){if(entry.object.type==='zone'||entry.object.type==='text')continue;b.strokeStyle=entry.object.kind==='edge'?(entry.object.type==='signal'?'#aa98c0':'#88aca5'):'#91a7ab';b.lineWidth=1/scale;b.beginPath();for(const line of entry.lines){b.moveTo(line.a.x,line.a.y);b.lineTo(line.b.x,line.b.y);}b.stroke();}}
  c.drawImage(minimapCache.canvas,0,0);c.save();c.translate(ox,oy);c.scale(scale,scale);const bounds=camera.bounds;c.fillStyle='#00867e0e';c.fillRect(bounds.x,bounds.y,bounds.maxX-bounds.x,bounds.maxY-bounds.y);c.strokeStyle='#00867e';c.lineWidth=1/scale;c.strokeRect(bounds.x,bounds.y,bounds.maxX-bounds.x,bounds.maxY-bounds.y);c.restore();
}

