store.subscribe(({label})=>{state.selected=new Set([...state.selected].filter(id=>objectFor(id)));if(!store.documents.some(d=>d.id===state.docId))state.docId=store.documents[0].id;state.openDocs=state.openDocs.filter(id=>store.documents.some(d=>d.id===id));el('save-state').textContent='Unsaved changes';clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>saveLocal(),500);invalidate({scene:true,ui:true});});
